window.AUTH=window.AUTH||{};window.AUTH["07-608"]={"d":"07-608","id":"2008/07-608","n":"United States v. Hayes","src":["osg"],"briefs":[{"k":"reply","label":"Reply brief for the United States","date":"","url":"https://www.justice.gov/osg/media/216231/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/united-states-v-hayes-reply-merits","n":83}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep555/usrep555415/usrep555415.pdf","tr":true,"items":[{"t":"case","label":"Barnhart v. Thomas","cite":"540 U.S. 20","y":2003,"id":"2003/02-763","sc":1,"op":3,"sum":"The Court held that the SSA's decision had been a reasonable interpretation of the statute and was therefore entitled to deference under Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc., 467 U.S. 837.","sumSrc":"Oyez","by":{"0":"8"}},{"t":"case","label":"Barrett v. United States","cite":"423 U.S. 212","y":1976,"id":"1975/74-5566","sc":1,"sum":"The provision of the Gun Control Act of 1968, 18 U. S. C. § 922 (h), making it unlawful for a convicted felon, inter alia, \"to receive any firearm or ammunition which has been shipped or transported in interstate or foreign commerce,\" held to apply to a convicted felon's intrastate purchase from a retail dealer of a firearm that previously, but independently of the felon's receipt, had been transported in interstate …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Begay v. United States","cite":"128 S. Ct. 1581","y":2008,"id":"2007/06-11543","sc":1,"sum":"In a 6-3 vote, the Court held that Begay's DWI convictions did not qualify as \"violent felonies\" because they were too different from the violent felony examples provided by Congress in the Armed Career Criminal Act (such as burglary, arson and extortion). Therefore, Begay should not have been subject to the mandatory sentencing hike.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Boumediene v. Bush","cite":"128 S. Ct. 2229","y":2008,"id":"2007/06-1195","sc":1,"sum":"The Court held that the Military Commissions Act of 2006 violated the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Bryan v. United States","cite":"524 U.S. 184","y":1998,"id":"1997/96-8422","sc":1,"sum":"The Court held that the term \"willfully\" in section 924(a)(1)(D) requires proof only that the defendant knew his conduct was unlawful, not that he also knew of the federal licensing requirement.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Caron v. United States","cite":"524 U.S. 308","y":1998,"id":"1997/97-6270","sc":1,"sum":"The Court held that \"Massachusetts treats [Caron] as too dangerous to trust with handguns, though it accords this right to law-abiding citizens.","sumSrc":"Oyez","by":{"0":"25, 26"}},{"t":"case","label":"CPSC v. GTE Sylvania, Inc.","cite":"447 U.S. 102","y":1980,"id":"1979/79-521","sc":1,"op":2,"sum":"Section 6 (b) (1) governs the disclosure of records by the Commission pursuant to a request under the FOIA.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Dada v. Mukasey","cite":"128 S. Ct. 2307","y":2008,"id":"2007/06-1181","sc":1,"sum":"Justice Anthony Kennedy, joined by four other Justices, stated that an alien has two options in such a case: he may abide by the terms of the voluntary departure and leave the country on time, maintaining the re-entry perks, or withdraw the voluntary departure request and remain in the country to pursue the motion to reopen. If the alien chooses the second option, he may become subject to deportation proceedings.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"District of Columbia v. Heller","cite":"128 S. Ct. 2783","y":2008,"id":"2007/07-290","sc":1,"sum":"The Court found a District of Columbia law strictly regulating gun ownership to be unconstitutional.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Dunn v. CFTC","cite":"519 U.S. 465","y":1997,"id":"1996/95-1181","sc":1,"sum":"The Court ruled that the \"Treasury Amendment\" of the Commodity Exchange Act exempts from the Commodity Futures Trading Commission regulation off exchange trading in foreign currency options. \"The arguments favoring each side in the important public policy dispute over whether off exchange foreign currency options should be exempt from CEA regulation are best addressed to the Congress, not the Courts,\" wrote Justice Stevens.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"First Nat’l Bank v. Missouri","cite":"263 U.S. 640","y":1924,"id":"scdb/1923-214","sc":1,"op":3,"ar":6,"sum":"1. National banks are subject to state laws that do not interfere with the purposes of their creation, tend to destroy or impair their efficiency as federal agencies, of conflict with the laws of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"5"}},{"t":"case","label":"Gillespie v. City of Indianapolis","cite":"185 F.3d 693","y":1999,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/185/693/","by":{"0":"23"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"0":"8"}},{"t":"case","label":"Jones v. United States","cite":"526 U.S. 227","y":1999,"id":"1998/97-6203","sc":1,"sum":"Authored by Justice David H. Souter, the Court ruled that the federal carjacking law established three separate offenses by the specification of elements, each of which must be charged by indictment, proved beyond a reasonable doubt, and submitted to a jury for its verdict.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Kennedy v. Louisiana","cite":"2008 WL 4414670","y":2008,"court":"Oct. 1","by":{"0":"7"}},{"t":"case","label":"Lewis v. United States","cite":"523 U.S. 155","y":1998,"id":"1997/96-7151","sc":1,"sum":"The Court held that, because the ACA does not make Louisiana's first-degree murder statute part of federal law, the federal second-degree murder statute governs Lewis' crime.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Moskal v. United States","cite":"498 U.S. 103","y":1990,"id":"1990/89-964","sc":1,"sum":"A person who receives genuine vehicle titles, knowing that they incorporate fraudulently tendered odometer readings, receives those titles knowing them to have been \"falsely made\" in violation of § 2314.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 26"}},{"t":"case","label":"Munaf v. Geren","cite":"128 S. Ct. 2207","y":2008,"id":"2007/06-1666","sc":1,"sum":"Held that the habeas corpus statute extends to American citizens held overseas by American forces operating subject to an American chain of command even if part of a larger multinational force.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Muscarello v. United States","cite":"524 U.S. 125","y":1998,"id":"1997/96-1654","sc":1,"sum":"The Court held that the phrase \"carries a firearm\" applies to a person who knowingly possesses and conveys firearms in a vehicle, including in the locked glove compartment or trunk of a car, which the person accompanies.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"ar":2,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"People v. Pickens","cite":"822 N.E.2d 58","y":2004,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/N.E.2d/822/58/","by":{"0":"3"}},{"t":"case","label":"Reno v. Koray","cite":"515 U.S. 50","y":1995,"id":"1994/94-790","sc":1,"sum":"The time respondent spent at the treatment center while \"released\" on bail was not \"official detention\" within the meaning of §3585(b).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Rothgery v. Gillespie County","cite":"128 S. Ct. 2578","y":2008,"id":"2007/07-440","sc":1,"sum":"In an 8-1 ruling, the Court held that a criminal defendant's initial appearance before a judge marks the beginning of the proceedings against him and triggers the defendant's Sixth Amendment right to counsel whether or not a prosecutor is aware of or involved in that appearance. This right to counsel applies whenever a defendant learns of the charges against him and has his liberty subject to restriction.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"S&E Contractors, Inc. v. United States","cite":"406 U.S. 1","y":1972,"id":"1971/70-88","sc":1,"sum":"In a contract disputes procedure, the Atomic Energy Commission (AEC) approved claims of its contractor for additional compensation. In response to an AEC certifying officer's request for advice as to one item, however, the General Accounting Office (GAO) ruled that the claims could not be certified for payment. When the AEC then refused to pay the compensation, the contractor brought suit in the Court of Claims …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Salinas v. United States","cite":"522 U.S. 52","y":1997,"id":"1997/96-738","sc":1,"sum":"The Court held that section 666(a)(1)(B) does not require the Government to prove the bribe in question had a demonstrated effect upon federal funds.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"South Dakota v. Dole","cite":"483 U.S. 203","y":1987,"id":"1986/86-260","sc":1,"sum":"The Court ruled that Congress did not exceed its spending powers or violate the Twenty-First Amendment when it conditioned the award of federal highway funds on states' adoption of a uniform minimum drinking age.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"State v. Coffin","cite":"191 P.3d 244","y":2008,"court":"Idaho Ct. App.","url":"https://www.courtlistener.com/c/P.3d/191/244/","by":{"0":"3"}},{"t":"case","label":"State v. Robinson","cite":"2008 WL 4377860","y":2008,"court":"Ohio Ct. App. Sept. 29","by":{"0":"3"}},{"t":"case","label":"State v. Rodriquez","cite":"636 N.W.2d 234","y":2001,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/636/234/","by":{"0":"3"}},{"t":"case","label":"State v. Roman","cite":"2008 WL 4173821","y":2008,"court":"Haw. Sept. 11","ar":1,"by":{"0":"3"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"0":"9"}},{"t":"case","label":"United States v. Barnes","cite":"295 F.3d 1354","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/295/1354/","op":5,"ar":1,"sum":"Rejecting the view that “Con­ gress remedied one disparity—between felony and misde­ meanor domestic violence convictions—while at the same time creating a new disparity among (and sometimes, within) states”.","sumSrc":"opinion","by":{"0":"3, 6, 7"}},{"t":"case","label":"United States v. Bean","cite":"537 U.S. 71","y":2002,"id":"2002/01-704","sc":1,"sum":"The Court held that the absence of an actual denial of Bean's petition by ATF precludes judicial review.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"United States v. Belless","cite":"338 F.3d 1063","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/338/1063/","op":2,"by":{"0":"22"}},{"t":"case","label":"United States v. Chavez","cite":"204 F.3d 1305","y":2000,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/204/1305/","op":1,"by":{"0":"12"}},{"t":"case","label":"United States v. Chester, Crim. No. 2:08-00105","cite":"2008 WL 4534210","y":2008,"court":"S.D. W. Va. Oct. 7","by":{"0":"22"}},{"t":"case","label":"United States v. Hutzell","cite":"217 F.3d 966","y":2000,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/217/966/","by":{"0":"23"}},{"t":"case","label":"United States v. Meade","cite":"175 F.3d 215","y":1999,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/175/215/","op":2,"by":{"0":"23"}},{"t":"case","label":"United States v. Ressam","cite":"128 S. Ct. 1858","y":2008,"id":"2007/07-455","sc":1,"sum":"The Court determined 8-1 that because Ressam was in possession of the explosives at the time he made the false statement to the customs agent he was therefore carrying them during the commission of that felony. Justice John Paul Stevens, in his majority opinion, refused to over-analyze the language of the statute and applied the word \"during\" in its most obvious sense.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"United States v. Rodriquez","cite":"128 S. Ct. 1783","y":2008,"id":"2007/06-1646","sc":1,"sum":"The Court held 6-3 that although the elements of a particular crime may not be considered \"serious,\" a defendant's prior record will have a considerable bearing on making the determination. A crime's seriousness may be greatly enhanced when its maximum sentence is increased due to the defendant's prior convictions for similar or related crimes.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"United States v. Shelton","cite":"325 F.3d 553","y":2003,"url":"https://www.courtlistener.com/c/F.3d/325/553/","op":1,"by":{"0":"23"}},{"t":"case","label":"United States v. Skoien","cite":"2008 U.S. Dist. LEXIS 66105","y":2008,"court":"W.D. Wis. Aug. 27","by":{"0":"22"}},{"t":"case","label":"United States v. Smith","cite":"171 F.3d 617","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/171/617/","op":1,"by":{"0":"23"}},{"t":"case","label":"United States v. White, Crim. No. 07-00361-WS","cite":"2008 WL 3211298","y":2008,"court":"S.D. Ala. Aug. 6","by":{"0":"22"}},{"t":"const","label":"Amendment II","clauses":[["second-amendment","Second Amendment"]],"text":"A well regulated Militia, being necessary to the security of a free State, the right of the people to keep and bear Arms, shall not be infringed.","by":{"0":"21, 22, 24"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"23"}},{"t":"usc","label":"18 U.S.C. § 13","url":"https://www.law.cornell.edu/uscode/text/18/13","subs":["(a)"],"by":{"0":"12"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(s)","(t)(1)(B)(ii)","(t)(2)","(d)","(g)","(g)(9)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"0":"14, 16, 14, 14, 20, 15, 15, 23, passim"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","stext":{"head":"§1. Words denoting number, gender, and so forth","paras":[[0,"In determining the meaning of any Act of Congress, unless the context indicates otherwise—"],[1,"words importing the singular include and apply to several persons, parties, or things;"],[1,"words importing the plural include the singular;"],[1,"words importing the masculine gender include the feminine as well;"],[1,"words used in the present tense include the future as well as the present;"],[1,"the words \"insane\" and \"insane person\" shall include every idiot, insane person, and person non compos mentis;"],[1,"the words \"person\" and \"whoever\" include corporations, companies, associations, firms, partnerships, societies, and joint stock companies, as well as individuals;"],[1,"\"officer\" includes any person authorized by law to perform the duties of the office;"],[1,"\"signature\" or \"subscription\" includes a mark when the person making the same intended it as such;"],[1,"\"oath\" includes affirmation, and \"sworn\" includes affirmed;"],[1,"\"writing\" includes printing and typewriting and reproductions of visual symbols by photographing, multigraphing, mimeographing, manifolding, or otherwise."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/1/1?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":2,"head":"§1. Words denoting number, gender, and so forth","tname":"General Provisions","by":{"0":"5"}},{"t":"law","label":"Pub. L. No. 103-322","url":"https://www.govinfo.gov/link/statute/108/1932","by":{"0":"13"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","subs":["(a)"],"by":{"0":"7"}},{"t":"usc","label":"18 U.S.C. § 3","url":"https://www.law.cornell.edu/uscode/text/18/3","by":{"0":"7"}},{"t":"usc","label":"18 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/18/16","subs":["(a)","(b)"],"stext":{"head":"§16. Crime of violence defined","paras":[[0,"The term \"crime of violence\" means—"],[1,"(a) an offense that has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(b) any other offense that is a felony and that, by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/16?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§16. Crime of violence defined","tname":"Crimes and Criminal Procedure","by":{"0":"4, 7"}},{"t":"usc","label":"18 U.S.C. § 113","url":"https://www.law.cornell.edu/uscode/text/18/113","subs":["(a)(4)"],"by":{"0":"12, 12"}},{"t":"usc","label":"18 U.S.C. § 373","url":"https://www.law.cornell.edu/uscode/text/18/373","subs":["(a)"],"by":{"0":"4"}},{"t":"usc","label":"18 U.S.C. § 521","url":"https://www.law.cornell.edu/uscode/text/18/521","subs":["(b)","(c)(2)","(c)(3)","(d)"],"by":{"0":"7, 4, 7, 7"}},{"t":"usc","label":"18 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/18/921","subs":["(a)(33)(A)","(a)(33)(A)(ii)"],"stext":{"head":"§921. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"person\" and the term \"whoever\" include any individual, corporation, company, association, firm, partnership, society, or joint stock company."],[0,"(2) The term \"interstate or foreign commerce\" includes commerce between any place in a State and any place outside of that State, or within any possession of the United States (not including the Canal Zone) or the District of Columbia, but such term does not include commerce between places within the same State but through any place outside of that State. The term \"State\" includes the District of Columbia, the Commonwealth of Puerto Rico, and the possessions of the United States (not including the Canal Zone)."],[0,"(3) The term \"firearm\" means (A) any weapon (including a starter gun) which will or is designed to or may readily be converted to expel a projectile by the action of an explosive; (B) the frame or receiver of any such weapon; (C) any firearm muffler or firearm silencer; or (D) any destructive device. Such term does not include an antique firearm."],[0,"(4) The term \"destructive device\" means—"],[1,"(A) any explosive, incendiary, or poison gas—"],[2,"(i) bomb,"],[2,"(ii) grenade,"],[2,"(iii) rocket having a propellant charge of more than four ounces,"],[2,"(iv) missile having an explosive or incendiary charge of more than one-quarter ounce,"],[2,"(v) mine, or"],[2,"(vi) device similar to any of the devices described in the preceding clauses;"],[1,"(B) any type of weapon (other than a shotgun or a shotgun shell which the Attorney General finds is generally recognized as particularly suitable for sporting purposes) by whatever name known which will, or which may be readily converted to, expel a projectile by the action of an explosive or other propellant, and which has any barrel with a bore of more than one-half inch in diameter; and"],[1,"(C) any combination of parts either designed or intended for use in converting any device into any destructive device described in subparagraph (A) or (B) and from which a destructive device may be readily assembled."],[0,"The term \"destructive device\" shall not include any device which is neither designed nor redesigned for use as a weapon; any device, although originally designed for use as a weapon, which is redesigned for use as a signaling, pyrotechnic, line throwing, safety, or similar device; surplus ordnance sold, loaned, or given by the Secretary of the Army pursuant to the provisions of section 7684(2), 7685, or 7686 of title 10; or any other device which the Attorney General finds is not likely to be used as a weapon, is an antique, or is a rifle which the owner intends to use solely for sporting, recreational or cultural purposes."],[0,"(5) The term \"shotgun\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire through a smooth bore either a number of ball shot or a single projectile for each single pull of the trigger."],[0,"(6) The term \"short-barreled shotgun\" means a shotgun having one or more barrels less than eighteen inches in length and any weapon made from a shotgun (whether by alteration, modification or otherwise) if such a weapon as modified has an overall length of less than twenty-six inches."],[0,"(7) The term \"rifle\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire only a single projectile through a rifled bore for each single pull of the trigger."],[0,"(8) The term \"short-barreled rifle\" means a rifle having one or more barrels less than sixteen inches in length and any weapon made from a rifle (whether by alteration, modification, or otherwise) if such weapon, as modified, has an overall length of less than twenty-six inches."],[0,"(9) The term \"importer\" means any person engaged in the business of importing or bringing firearms or ammunition into the United States for purposes of sale or distribution; and the term \"licensed importer\" means any such person licensed under the provisions of this chapter."],[0,"(10) The term \"manufacturer\" means any person engaged in the business of manufacturing firearms or ammunition for purposes of sale or distribution; and the term \"licensed manufacturer\" means any such person licensed under the provisions of this chapter."],[0,"(11) The term \"dealer\" means (A) any person engaged in the business of selling firearms at wholesale or retail, (B) any person engaged in the business of repairing firearms or of making or fitting special barrels, stocks, or trigger mechanisms to firearms, or (C) any person who is a pawnbroker. The term \"licensed dealer\" means any dealer who is licensed under the provisions of this chapter."],[0,"(12) The term \"pawnbroker\" means any person whose business or occupation includes the taking or receiving, by way of pledge or pawn, of any firearm as security for the payment or repayment of money."],[0,"(13) The term \"collector\" means any person who acquires, holds, or disposes of firearms as curios or relics, as the Attorney General shall by regulation define, and the term \"licensed collector\" means any such person licensed under the provisions of this chapter."],[0,"(14) The term \"indictment\" includes an indictment or information in any court under which a crime punishable by imprisonment for a term exceeding one year may be prosecuted."],[0,"(15) The term \"fugitive from justice\" means any person who has fled from any State to avoid prosecution for a crime or to avoid giving testimony in any criminal proceeding."],[0,"(16) The term \"antique firearm\" means—"],[1,"(A) any firearm (including any firearm with a matchlock, flintlock, percussion cap, or similar type of ignition system) manufactured in or before 1898; or"],[1,"(B) any replica of any firearm described in subparagraph (A) if such replica—"],[2,"(i) is not designed or redesigned for using rimfire or conventional centerfire fixed ammunition, or"],[2,"(ii) uses rimfire or conventional centerfire fixed ammunition which is no longer manufactured in the United States and which is not readily available in the ordinary channels of commercial trade; or"],[1,"(C) any muzzle loading rifle, muzzle loading shotgun, or muzzle loading pistol, which is designed to use black powder, or a black powder substitute, and which cannot use fixed ammunition. For purposes of this subparagraph, the term \"antique firearm\" shall not include any weapon which incorporates a firearm frame or receiver, any firearm which is converted into a muzzle loading weapon, or any muzzle loading weapon which can be readily converted to fire fixed ammunition by replacing the barrel, bolt, breechblock, or any combination thereof."],[0,"(17)(A) The term \"ammunition\" means ammunition or cartridge cases, primers, bullets, or propellent powder designed for use in any firearm."],[0,"(B) The term \"armor piercing ammunition\" means—"],[1,"(i) a projectile or projectile core which may be used in a handgun and which is constructed entirely (excluding the presence of traces of other substances) from one or a combination of tungsten alloys, steel, iron, brass, bronze, beryllium copper, or depleted uranium; or"],[1,"(ii) a full jacketed projectile larger than .22 caliber designed and intended for use in a handgun and whose jacket has a weight of more than 25 percent of the total weight of the projectile."],[0,"(C) The term \"armor piercing ammunition\" does not include shotgun shot required by Federal or State environmental or game regulations for hunting purposes, a frangible projectile designed for target shooting, a projectile which the Attorney General finds is primarily intended to be used for sporting purposes, or any other projectile or projectile core which the Attorney General finds is intended to be used for industrial purposes, including a charge used in an oil and gas well perforating device."],[0,"(18) The term \"Attorney General\" means the Attorney General of the United States 1"],[0,"(19) The term \"published ordinance\" means a published law of any political subdivision of a State which the Attorney General determines to be relevant to the enforcement of this chapter and which is contained on a list compiled by the Attorney General, which list shall be published in the Federal Register, revised annually, and furnished to each licensee under this chapter."],[0,"(20) The term \"crime punishable by imprisonment for a term exceeding one year\" does not include—"],[1,"(A) any Federal or State offenses pertaining to antitrust violations, unfair trade practices, restraints of trade, or other similar offenses relating to the regulation of business practices, or"],[1,"(B) any State offense classified by the laws of the State as a misdemeanor and punishable by a term of imprisonment of two years or less."],[0,"What constitutes a conviction of such a crime shall be determined in accordance with the law of the jurisdiction in which the proceedings were held. Any conviction which has been expunged, or set aside or for which a person has been pardoned or has had civil rights restored shall not be considered a conviction for purposes of this chapter, unless such pardon, expungement, or restoration of civil rights expressly provides that the person may not ship, transport, possess, or receive firearms."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/921?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§921. Definitions","tname":"Crimes and Criminal Procedure","by":{"0":"passim, 3, 22"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(b)","(c)(3)(A)","(c)(3)(B)","(e)(1)","(e)(2)(B)(i)","(o)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"7, 4, 7, 7, 4, 7"}},{"t":"usc","label":"18 U.S.C. § 3156","url":"https://www.law.cornell.edu/uscode/text/18/3156","subs":["(a)(4)(B)"],"by":{"0":"7"}},{"t":"usc","label":"18 U.S.C. § 3559","url":"https://www.law.cornell.edu/uscode/text/18/3559","subs":["(c)(1)(B)","(c)(2)(F)(i)","(c)(2)(F)(ii)","(d)(2)"],"stext":{"head":"§3559. Sentencing classification of offenses","paras":[[0,"(a) Classification.—An offense that is not specifically classified by a letter grade in the section defining it, is classified if the maximum term of imprisonment authorized is—"],[1,"(1) life imprisonment, or if the maximum penalty is death, as a Class A felony;"],[1,"(2) twenty-five years or more, as a Class B felony;"],[1,"(3) less than twenty-five years but ten or more years, as a Class C felony;"],[1,"(4) less than ten years but five or more years, as a Class D felony;"],[1,"(5) less than five years but more than one year, as a Class E felony;"],[1,"(6) one year or less but more than six months, as a Class A misdemeanor;"],[1,"(7) six months or less but more than thirty days, as a Class B misdemeanor;"],[1,"(8) thirty days or less but more than five days, as a Class C misdemeanor; or"],[1,"(9) five days or less, or if no imprisonment is authorized, as an infraction."],[0,"(b) Effect of Classification.—Except as provided in subsection (c), an offense classified under subsection (a) carries all the incidents assigned to the applicable letter designation, except that the maximum term of imprisonment is the term authorized by the law describing the offense."],[0,"(c) Imprisonment of Certain Violent Felons.—"],[1,"(1) Mandatory life imprisonment.—Notwithstanding any other provision of law, a person who is convicted in a court of the United States of a serious violent felony shall be sentenced to life imprisonment if—"],[2,"(A) the person has been convicted (and those convictions have become final) on separate prior occasions in a court of the United States or of a State of—"],[3,"(i) 2 or more serious violent felonies; or"],[3,"(ii) one or more serious violent felonies and one or more serious drug offenses; and"],[2,"(B) each serious violent felony or serious drug offense used as a basis for sentencing under this subsection, other than the first, was committed after the defendant's conviction of the preceding serious violent felony or serious drug offense."],[1,"(2) Definitions.—For purposes of this subsection—"],[2,"(A) the term \"assault with intent to commit rape\" means an offense that has as its elements engaging in physical contact with another person or using or brandishing a weapon against another person with intent to commit aggravated sexual abuse or sexual abuse (as described in sections 2241 and 2242);"],[2,"(B) the term \"arson\" means an offense that has as its elements maliciously damaging or destroying any building, inhabited structure, vehicle, vessel, or real property by means of fire or an explosive;"],[2,"(C) the term \"extortion\" means an offense that has as its elements the extraction of anything of value from another person by threatening or placing that person in fear of injury to any person or kidnapping of any person;"],[2,"(D) the term \"firearms use\" means an offense that has as its elements those described in section 924(c) or 929(a), if the firearm was brandished, discharged, or otherwise used as a weapon and the crime of violence or drug trafficking crime during and relation to which the firearm was used was subject to prosecution in a court of the United States or a court of a State, or both;"],[2,"(E) the term \"kidnapping\" means an offense that has as its elements the abduction, restraining, confining, or carrying away of another person by force or threat of force;"],[2,"(F) the term \"serious violent felony\" means—"],[3,"(i) a Federal or State offense, by whatever designation and wherever committed, consisting of murder (as described in section 1111); manslaughter other than involuntary manslaughter (as described in section 1112); assault with intent to commit murder (as described in section 113(a)); assault with intent to commit rape; aggravated sexual abuse and sexual abuse (as described in sections 2241 and 2242); abusive sexual contact (as described in sections 2244(a)(1) and (a)(2)); kidnapping; aircraft piracy (as described in section 46502 of Title 49); robbery (as described in section 2111, 2113, or 2118); carjacking (as described in section 2119); extortion; arson; firearms use; firearms possession (as described in section 924(c)); or attempt, conspiracy, or solicitation to commit any of the above offenses; and"],[3,"(ii) any other offense punishable by a maximum term of imprisonment of 10 years or more that has as an element the use, attempted use, or threatened use of physical force against the person of another or that, by its nature, involves a substantial risk that physical force against the person of another may be used in the course of committing the offense;"],[2,"(G) the term \"State\" means a State of the United States, the District of Columbia, and a commonwealth, territory, or possession of the United States; and"],[2,"(H) the term \"serious drug offense\" means—"],[3,"(i) an offense that is punishable under section 401(b)(1)(A) or 408 of the Controlled Substances Act (21 U.S.C. 841(b)(1)(A), 848) or section 1010(b)(1)(A) of the Controlled Substances Import and Export Act (21 U.S.C. 960(b)(1)(A)); or"],[3,"(ii) an offense under State law that, had the offense been prosecuted in a court of the United States, would have been punishable under section 401(b)(1)(A) or 408 of the Controlled Substances Act (21 U.S.C. 841(b)(1)(A), 848) or section 1010(b)(1)(A) of the Controlled Substances Import and Export Act (21 U.S.C. 960(b)(1)(A))."],[1,"(3) Nonqualifying felonies.—"],[2,"(A) Robbery in certain cases.—Robbery, an attempt, conspiracy, or solicitation to commit robbery; or an offense described in paragraph (2)(F)(ii) shall not serve as a basis for sentencing under this subsection if the defendant establishes by clear and convincing evidence that—"],[3,"(i) no firearm or other dangerous weapon was used in the offense and no threat of use of a firearm or other dangerous weapon was involved in the offense; and"],[3,"(ii) the offense did not result in death or serious bodily injury (as defined in section 1365) to any person."],[2,"(B) Arson in certain cases.—Arson shall not serve as a basis for sentencing under this subsection if the defendant establishes by clear and convincing evidence that—"],[3,"(i) the offense posed no threat to human life; and"],[3,"(ii) the defendant reasonably believed the offense posed no threat to human life."],[1,"(4) Information filed by united states attorney.—The provisions of section 411(a) of the Controlled Substances Act (21 U.S.C. 851(a)) shall apply to the imposition of sentence under this subsection."],[1,"(5) Rule of construction.—This subsection shall not be construed to preclude imposition of the death penalty."],[1,"(6) Special provision for indian country.—No person subject to the criminal jurisdiction of an Indian tribal government shall be subject to this subsection for any offense for which Federal jurisdiction is solely predicated on Indian country (as defined in section 1151) and which occurs within the boundaries of such Indian country unless the governing body of the tribe has elected that this subsection have effect over land and persons subject to the criminal jurisdiction of the tribe."],[1,"(7) Resentencing upon overturning of prior conviction.—If the conviction for a serious violent felony or serious drug offense that was a basis for sentencing under this subsection is found, pursuant to any appropriate State or Federal procedure, to be unconstitutional or is vitiated on the explicit basis of innocence, or if the convicted person is pardoned on the explicit basis of innocence, the person serving a sentence imposed under this subsection shall be resentenced to any sentence that was available at the time of the original sentencing."],[0,"(d) Death or Imprisonment for Crimes Against Children.—"],[1,"(1) In general.—Subject to paragraph (2) and notwithstanding any other provision of law, a person who is convicted of a Federal offense that is a serious violent felony (as defined in subsection (c)) or a violation of section 2422, 2423, or 2251 shall, unless the sentence of death is imposed, be sentenced to imprisonment for life, if—"],[2,"(A) the victim of the offense has not attained the age of 14 years;"],[2,"(B) the victim dies as a result of the offense; and"],[2,"(C) the defendant, in the course of the offense, engages in conduct described in section 3591(a)(2)."],[1,"(2) Exception.—With respect to a person convicted of a Federal offense described in paragraph (1), the court may impose any lesser sentence that is authorized by law to take into account any substantial assistance provided by the defendant in the investigation or prosecution of another person who has committed an offense, in accordance with the Federal Sentencing Guidelines and the policy statements of the Federal Sentencing Commission pursuant to section 994(p) of title 28, or for other good cause."],[0,"(e) Mandatory Life Imprisonment for Repeated Sex Offenses Against Children.—"],[1,"(1) In general.—A person who is convicted of a Federal sex offense in which a minor is the victim shall be sentenced to life imprisonment if the person has a prior sex conviction in which a minor was the victim, unless the sentence of death is imposed."],[1,"(2) Definitions.—For the purposes of this subsection—"],[2,"(A) the term \"Federal sex offense\" means an offense under section 1591 (relating to sex trafficking of children), 2241 (relating to aggravated sexual abuse), 2242 (relating to sexual abuse), 2244(a)(1) (relating to abusive sexual contact), 2245 (relating to sexual abuse resulting in death), 2251 (relating to sexual exploitation of children), 2251A (relating to selling or buying of children), 2422(b) (relating to coercion and enticement of a minor into prostitution), or 2423(a) (relating to transportation of minors);"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3559?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3559. Sentencing classification of offenses","tname":"Crimes and Criminal Procedure","by":{"0":"7, 7, 4, 7"}},{"t":"usc","label":"25 U.S.C. § 2803","url":"https://www.law.cornell.edu/uscode/text/25/2803","subs":["(3)(c)"],"stext":{"head":"§2803. Law enforcement authority","paras":[[0,"The Secretary may charge employees of the Bureau with law enforcement responsibilities and may authorize those employees to—"],[1,"(1) carry firearms;"],[1,"(2) execute or serve warrants, summonses, or other orders relating to a crime committed in Indian country and issued under the laws of—"],[2,"(A) the United States (including those issued by a Court of Indian Offenses under regulations prescribed by the Secretary or offenses processed by the Central Violations Bureau); or"],[2,"(B) an Indian tribe if authorized by the Indian tribe;"],[1,"(3) make an arrest without a warrant for an offense committed in Indian country if—"],[2,"(A) the offense is committed in the presence of the employee,1"],[2,"(B) the offense is a felony and the employee has probable cause to believe that the person to be arrested has committed, or is committing, the felony;"],[2,"(C) the offense is a misdemeanor crime of domestic violence, dating violence, stalking, or violation of a protection order and has, as an element, the use or attempted use of physical force, or the threatened use of a deadly weapon, committed by a current or former spouse, parent, or guardian of the victim, by a person with whom the victim shares a child in common, by a person who is cohabitating with or has cohabited with the victim as a spouse, parent, or guardian, or by a person similarly situated to a spouse, parent or guardian of the victim, and the employee has probable cause to believe that the person to be arrested has committed, or is committing the crime; or"],[2,"(D)(i) the offense involves—"],[3,"(I) a misdemeanor controlled substance offense in violation of—"],[4,"(aa) the Controlled Substances Act (21 U.S.C. 801 et seq.);"],[4,"(bb) title IX of the Personal Responsibility and Work Opportunity Reconciliation Act of 1996 (21 U.S.C. 862a et seq.); 2 or"],[4,"(cc) section 865 of title 21;"],[3,"(II) a misdemeanor firearms offense in violation of chapter 44 of title 18;"],[3,"(III) a misdemeanor assault in violation of chapter 7 of title 18; or"],[3,"(IV) a misdemeanor liquor trafficking offense in violation of chapter 59 of title 18; and"],[2,"(ii) the employee has probable cause to believe that the individual to be arrested has committed, or is committing, the crime;"],[1,"(4) offer and pay a reward for services or information, or purchase evidence, assisting in the detection or investigation of the commission of an offense committed in Indian country or in the arrest of an offender against the United States;"],[1,"(5) make inquiries of any person, and administer to, or take from, any person an oath, affirmation, or affidavit, concerning any matter relevant to the enforcement or carrying out in Indian country of a law of either the United States or an Indian tribe that has authorized the employee to enforce or carry out tribal laws;"],[1,"(6) wear a prescribed uniform and badge or carry prescribed credentials;"],[1,"(7) perform any other law enforcement related duty; and"],[1,"(8) when requested, assist (with or without reimbursement) any Federal, tribal, State, or local law enforcement agency in the enforcement or carrying out of the laws or regulations the agency enforces or administers."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/2803?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2803. Law enforcement authority","tname":"Indians","by":{"0":"20"}},{"t":"usc","label":"42 U.S.C. § 3796gg","url":"https://www.law.cornell.edu/uscode/text/42/3796gg","by":{"0":"13"}},{"t":"usc","label":"42 U.S.C. § 3796hh","url":"https://www.law.cornell.edu/uscode/text/42/3796hh","by":{"0":"13"}}]};